async function generateVideoPoster(req,id,body={}){const d=await detail(req,id,{allowTrash:true});if(!d.ok)return d;const photo=d.payload.item,replaceExisting=body.replace_existing===true;if(!photo.is_original_owner)return bad(403,"Solo el propietario original puede generar la miniatura.");if(photo.media_type!=="video")return bad(400,"La miniatura solo puede generarse para vídeos.");const files=(await pool.query(`SELECT id,variant,provider,bucket,object_key,mime_type,width,height,size_bytes,checksum_sha256,etag FROM public.orange_photo_files WHERE family_id=$1::uuid AND photo_id=$2::uuid AND variant=ANY($3::text[])`,[d.payload.auth.familyId,id,["original","poster","thumbnail"]])).rows;if(!files.some(row=>row.variant==="original"))return bad(404,"El vídeo original no está disponible.");const currentPoster=files.find(row=>row.variant==="poster"),hasThumbnail=files.some(row=>row.variant==="thumbnail");if((currentPoster||hasThumbnail)&&!replaceExisting)return bad(409,"El vídeo ya dispone de miniatura. Indica que deseas sustituirla.");try{if(!replaceExisting){await processStoredOrangePhotoVideo(id,{createPoster:true,createPreview:false,updateMetadata:false});return detail(req,id,{allowTrash:true});}const processed=await processStoredOrangePhotoVideo(id,{createPoster:true,createPreview:false,updateMetadata:false,replacePoster:true}),created=processed.created.find(item=>item.variant==="poster");if(!created)throw new Error("No se pudo registrar la nueva miniatura.");const c=await pool.connect();let committed=false,phaseStarted=Date.now();try{await c.query('BEGIN');if(currentPoster){await c.query(`UPDATE public.orange_photo_files SET provider=$1,bucket=$2,object_key=$3,mime_type=$4,width=$5,height=$6,size_bytes=$7,checksum_sha256=$8,etag=$9 WHERE id=$10::uuid AND family_id=$11::uuid AND photo_id=$12::uuid`,[created.provider,created.bucket,created.object_key,created.mime_type,created.width,created.height,created.size_bytes,created.checksum_sha256,created.etag,currentPoster.id,d.payload.auth.familyId,id]);}else{await c.query(`INSERT INTO public.orange_photo_files(family_id,photo_id,variant,provider,bucket,object_key,mime_type,width,height,size_bytes,checksum_sha256,etag) VALUES($1,$2,'poster',$3,$4,$5,$6,$7,$8,$9,$10,$11)`,[d.payload.auth.familyId,id,created.provider,created.bucket,created.object_key,created.mime_type,created.width,created.height,created.size_bytes,created.checksum_sha256,created.etag]);}await c.query('COMMIT');committed=true;console.info("OrangePhotos poster replacement",{photo_id:id,phase:"replace_database_record",duration_ms:Date.now()-phaseStarted,object_key:created.object_key,message:"completed"});}catch(error){console.error("OrangePhotos poster replacement",{photo_id:id,phase:"replace_database_record",duration_ms:Date.now()-phaseStarted,object_key:created.object_key,message:error.message});await c.query('ROLLBACK').catch(()=>{});try{await deleteOrangePhotoObject(created);}catch(cleanupError){console.error("OrangePhotos replacement poster cleanup",{photo_id:id,phase:"delete_old_poster",duration_ms:0,object_key:created.object_key,message:cleanupError.message});}throw new Error("No se pudo registrar la nueva miniatura.",{cause:error});}finally{c.release();}if(committed&&currentPoster&&currentPoster.object_key!==created.object_key){phaseStarted=Date.now();try{await deleteOrangePhotoObject(currentPoster);console.info("OrangePhotos poster replacement",{photo_id:id,phase:"delete_old_poster",duration_ms:Date.now()-phaseStarted,object_key:currentPoster.object_key,message:"completed"});}catch(error){console.error("OrangePhotos poster replacement",{photo_id:id,phase:"delete_old_poster",duration_ms:Date.now()-phaseStarted,object_key:currentPoster.object_key,message:error.message});}}return detail(req,id,{allowTrash:true});}catch(error){return bad(500,"VIDEO_POSTER_FAILED",error?.message||"No se pudo generar la miniatura.");}}
async function trash(req,id,restore=false){const d=await detail(req,id,{allowTrash:true});if(!d.ok)return d;if(!d.payload.item.is_owner)return bad(403,"Solo el propietario puede gestionar la papelera.");const c=await pool.connect();try{await c.query('BEGIN');const locked=(await c.query(`SELECT li.photo_id,li.is_trashed FROM public.orange_photo_library_items li JOIN public.orange_photos p ON p.id=li.photo_id WHERE li.photo_id=$1::uuid AND p.family_id=$2::uuid AND li.user_id=$3::uuid FOR UPDATE OF li`,[id,d.payload.auth.familyId,d.payload.auth.userId])).rows[0];if(!locked){await c.query('ROLLBACK');return bad(409,"PHOTO_RETAINED_BY_LIBRARY","La foto no puede cambiar de estado porque ya no está disponible.");}await c.query(`UPDATE public.orange_photo_library_items SET is_trashed=$3::boolean,trashed_at=CASE WHEN $3::boolean THEN now() ELSE NULL END WHERE photo_id=$1::uuid AND user_id=$2::uuid`,[id,d.payload.auth.userId,!restore]);await recordPhotoEvent(c,{familyId:d.payload.auth.familyId,photoId:id,copyOwnerUserId:d.payload.auth.userId,actorUserId:d.payload.auth.userId,eventType:restore?'restored':'moved_to_trash',...clientContext(req)});await c.query('COMMIT');const refreshed=await detail(req,id,{allowTrash:true});return refreshed.ok?ok({item:refreshed.payload.item}):refreshed;}catch(error){await c.query('ROLLBACK').catch(()=>{});throw error;}finally{c.release();}}
async function addToLibrary(req,id){const auth=resolveAuthenticatedFamily(req);if(!auth.ok)return auth;if(!uuid(id))return bad(400,"Identificador no válido.");const sourceDetail=await detail(req,id);if(!sourceDetail.ok)return sourceDetail;if(sourceDetail.payload.item.is_owner)return ok({item:sourceDetail.payload.item,created:false});const sourceOwner=sourceDetail.payload.item.copy_owner_user_id;if(!uuid(sourceOwner))return bad(404,"UPLOAD_NOT_FOUND","Foto no encontrada.");const client=await pool.connect();try{await client.query('BEGIN');const physical=(await client.query(`SELECT id FROM public.orange_photos WHERE family_id=$1::uuid AND id=$2::uuid FOR UPDATE`,[auth.familyId,id])).rows[0];if(!physical){await client.query('ROLLBACK');return bad(404,"UPLOAD_NOT_FOUND","Foto no encontrada.");}const existing=(await client.query(`SELECT li.* FROM public.orange_photo_library_items li JOIN public.orange_photos p ON p.id=li.photo_id WHERE p.family_id=$1::uuid AND li.photo_id=$3::uuid AND li.user_id=$2::uuid FOR UPDATE OF li`,[auth.familyId,auth.userId,id])).rows[0];if(existing){const sourceStillAccessible=(await client.query(`SELECT 1 FROM public.orange_photos p JOIN public.orange_photo_library_items candidate ON candidate.photo_id=p.id AND candidate.user_id=$4::uuid WHERE p.family_id=$1::uuid AND p.id=$3::uuid AND candidate.is_trashed=false AND ${logicalCopyAccessibleSql('candidate','p')} LIMIT 1`,[auth.familyId,auth.userId,id,sourceOwner])).rows[0];if(!sourceStillAccessible){await client.query('ROLLBACK');return bad(404,"UPLOAD_NOT_FOUND","Foto no encontrada.");}if(existing.is_trashed){await client.query(`UPDATE public.orange_photo_library_items SET is_trashed=false,trashed_at=NULL,visibility='private',public_enabled=false,public_token=NULL,public_created_at=NULL,public_revoked_at=NULL WHERE photo_id=$1::uuid AND user_id=$2::uuid`,[id,auth.userId]);await client.query(`DELETE FROM public.orange_photo_shares WHERE photo_id=$1::uuid AND owner_user_id=$2::uuid`,[id,auth.userId]);}await client.query('COMMIT');const refreshed=await detail(req,id);return refreshed.ok?ok({item:refreshed.payload.item,created:false}):refreshed;}const result=await client.query(`INSERT INTO public.orange_photo_library_items(photo_id,user_id,title,description,captured_at,captured_at_source,timezone,latitude,longitude,altitude_meters,location_name,location_country,location_region,location_locality,location_source,visibility,is_trashed,trashed_at,public_enabled,public_token,public_created_at,public_revoked_at) SELECT candidate.photo_id,$2::uuid,candidate.title,candidate.description,candidate.captured_at,candidate.captured_at_source,candidate.timezone,candidate.latitude,candidate.longitude,candidate.altitude_meters,candidate.location_name,candidate.location_country,candidate.location_region,candidate.location_locality,candidate.location_source,'private',false,NULL,false,NULL,NULL,NULL FROM public.orange_photos p JOIN public.orange_photo_library_items candidate ON candidate.photo_id=p.id AND candidate.user_id=$3::uuid WHERE p.id=$1::uuid AND p.family_id=$4::uuid AND candidate.is_trashed=false AND ${logicalCopyAccessibleSql('candidate','p')} ON CONFLICT(photo_id,user_id) DO NOTHING RETURNING added_at`,[id,auth.userId,sourceOwner,auth.familyId]);if(!result.rowCount){await client.query('ROLLBACK');return bad(404,"UPLOAD_NOT_FOUND","Foto no encontrada.");}await client.query('COMMIT');const refreshed=await detail(req,id);return refreshed.ok?ok({item:refreshed.payload.item,created:true}):refreshed;}catch(error){await client.query('ROLLBACK').catch(()=>{});throw error;}finally{client.release();}}
