async function recordCompletedBulkDownload(req,items){
  const a=resolveAuthenticatedFamily(req);if(!a.ok)return;
  const context=clientContext(req),client=await pool.connect();
  try{
    await client.query('BEGIN');
    for(const item of items){
      await recordPhotoEvent(client,{familyId:a.familyId,photoId:item.id,copyOwnerUserId:item.copy_owner_user_id,actorUserId:a.userId,eventType:'bulk_downloaded',...context,metadata:{format:'zip',item_count:items.length}});
    }
    await client.query('COMMIT');
  }catch(error){
    await client.query('ROLLBACK').catch(()=>{});
    throw error;
  }finally{
    client.release();
  }
}
const downloadObject=record=>getOrangePhotoObjectStream(record);
async function downloadMany(req,body={}){
  const a=resolveAuthenticatedFamily(req);if(!a.ok)return a;
  let requested=body.photo_ids;
  if(typeof requested==="string"){try{requested=JSON.parse(requested);}catch{return bad(400,"INVALID_METADATA","La lista de fotos no es válida.");}}
  if(!Array.isArray(requested))return bad(400,"INVALID_METADATA","photo_ids debe ser una lista.");
  const ids=[...new Set(requested.map(value=>String(value||"").trim()))];
  if(ids.length<2)return bad(400,"INVALID_METADATA","Selecciona al menos dos elementos.");
  if(ids.length>MAX_ZIP_DOWNLOAD_ITEMS)return bad(400,"INVALID_METADATA","Puedes descargar un máximo de 500 elementos a la vez.");
  if(ids.some(id=>!uuid(id)))return bad(400,"INVALID_METADATA","Uno o más identificadores no son válidos.");
  const rows=(await pool.query(`SELECT p.id,p.original_filename,f.bucket,f.object_key,f.mime_type,f.size_bytes,li.user_id copy_owner_user_id FROM public.orange_photos p JOIN LATERAL (SELECT candidate.user_id FROM public.orange_photo_library_items candidate WHERE candidate.photo_id=p.id AND candidate.is_trashed=false AND ${logicalCopyAccessibleSql('candidate','p')} ORDER BY ${logicalCopyOrderSql('candidate','p')} LIMIT 1) li ON true JOIN public.orange_photo_files f ON f.photo_id=p.id AND f.family_id=p.family_id AND f.variant='original' WHERE p.family_id=$1::uuid AND p.id=ANY($3::uuid[])`,[a.familyId,a.userId,ids])).rows;
  if(rows.length!==ids.length)return bad(404,"UPLOAD_NOT_FOUND","Una o más fotos no existen, no son accesibles o no tienen original disponible.");
  const byId=new Map(rows.map(row=>[String(row.id),row]));
  return ok({items:ids.map(id=>byId.get(id))});
}
